@pytest.mark.tc('TC_APET_001')
def test_tc_apet_001_create_pet_with_valid_required_fields_re(api):
    """TC_APET_001: Create pet with valid required fields returns 200 and pet object

    Scenario: SC_APET_001
    Endpoint: POST  pet
    Expected: HTTP 200, Content-Type application json, response body contains id (int64), name (string), photoUrls (array of strings), status (enum available|pending|sold). Required fields name and photoUrls echoed back.
    """
    with api.step('create_pet_required_fields', method='POST', path='/pet'):
        api.send(
            {'method': 'POST',
             'path': '/pet',
             'headers': {'Content-Type': 'application/json'},
             'body': {'name': 'doggie', 'photoUrls': ['https://example.com/photo1.jpg']},
             'auth': 'petstore_auth',
             'save': {'pet_id': '$.id'},
             'expect': {'status': 200,
                        'headers': {'Content-Type': 'application/json'},
                        'json': [{'path': '$.id', 'op': 'type', 'value': 'integer'},
                                 {'path': '$.name', 'op': 'equals', 'value': 'doggie'},
                                 {'path': '$.photoUrls', 'op': 'type', 'value': 'array'},
                                 {'path': '$.photoUrls[0]', 'op': 'equals', 'value': 'https://example.com/photo1.jpg'},
                                 {'path': '$.status', 'op': 'type', 'value': 'string'}],
                        'schema': {'required': ['name', 'photoUrls'],
                                   'type': 'object',
                                   'properties': {'id': {'type': 'integer', 'format': 'int64'},
                                                  'name': {'type': 'string'},
                                                  'category': {'type': 'object', 'properties': {'id': {}, 'name': {}}},
                                                  'photoUrls': {'type': 'array', 'items': {'type': 'string'}},
                                                  'tags': {'type': 'array',
                                                           'items': {'type': 'object',
                                                                     'properties': {'id': {}, 'name': {}}}},
                                                  'status': {'type': 'string',
                                                             'enum': ['available', 'pending', 'sold']}}},
                        'max_ms': 3000}}
        )

